/* Dependency-free SVG charts, safe to render in server components. */

function pathFrom(points: [number, number][], smooth = true): string {
  if (points.length === 0) return "";
  if (!smooth || points.length < 3) {
    return points.map(([x, y], i) => `${i === 0 ? "M" : "L"}${x.toFixed(2)},${y.toFixed(2)}`).join(" ");
  }
  let d = `M${points[0][0].toFixed(2)},${points[0][1].toFixed(2)}`;
  for (let i = 1; i < points.length; i++) {
    const [x0, y0] = points[i - 1];
    const [x1, y1] = points[i];
    const cx = (x0 + x1) / 2;
    d += ` C${cx.toFixed(2)},${y0.toFixed(2)} ${cx.toFixed(2)},${y1.toFixed(2)} ${x1.toFixed(2)},${y1.toFixed(2)}`;
  }
  return d;
}

function scale(data: number[], w: number, h: number, pad = 2, max?: number): [number, number][] {
  const mx = max ?? Math.max(...data, 1e-9);
  const mn = 0;
  const n = Math.max(data.length - 1, 1);
  return data.map((v, i) => [
    (i / n) * (w - pad * 2) + pad,
    h - pad - ((v - mn) / (mx - mn || 1)) * (h - pad * 2),
  ]);
}

export function Sparkline({
  data,
  width = 120,
  height = 36,
  stroke = "#8a70fb",
  id,
}: {
  data: number[];
  width?: number;
  height?: number;
  stroke?: string;
  id: string;
}) {
  if (data.length === 0) return null;
  const pts = scale(data, width, height);
  const line = pathFrom(pts);
  const area = `${line} L${pts[pts.length - 1][0].toFixed(2)},${height} L${pts[0][0].toFixed(2)},${height} Z`;
  return (
    <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`} className="overflow-visible">
      <defs>
        <linearGradient id={`sg-${id}`} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={stroke} stopOpacity="0.35" />
          <stop offset="100%" stopColor={stroke} stopOpacity="0" />
        </linearGradient>
      </defs>
      <path d={area} fill={`url(#sg-${id})`} />
      <path d={line} fill="none" stroke={stroke} strokeWidth="1.5" strokeLinecap="round" />
    </svg>
  );
}

export function AreaChart({
  series,
  width = 720,
  height = 220,
  id,
  yLabel,
  xLabels = [],
  maxY,
}: {
  series: { name: string; data: number[]; color: string }[];
  width?: number;
  height?: number;
  id: string;
  yLabel?: (v: number) => string;
  xLabels?: string[];
  maxY?: number;
}) {
  const all = series.flatMap((s) => s.data);
  if (all.length === 0) return <p className="text-sm text-slate-500">No data yet.</p>;
  const max = maxY ?? Math.max(...all, 1e-9);
  const padL = 46;
  const padB = 22;
  const cw = width - padL - 8;
  const ch = height - padB - 8;
  const gridLines = 4;

  return (
    <div className="w-full overflow-x-auto">
      <svg
        width="100%"
        viewBox={`0 0 ${width} ${height}`}
        preserveAspectRatio="none"
        className="min-w-[480px]"
        style={{ height }}
      >
        <defs>
          {series.map((s, si) => (
            <linearGradient key={si} id={`ag-${id}-${si}`} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor={s.color} stopOpacity="0.30" />
              <stop offset="100%" stopColor={s.color} stopOpacity="0" />
            </linearGradient>
          ))}
        </defs>
        {Array.from({ length: gridLines + 1 }, (_, i) => {
          const y = 8 + (ch / gridLines) * i;
          const v = max * (1 - i / gridLines);
          return (
            <g key={i}>
              <line x1={padL} x2={width - 8} y1={y} y2={y} stroke="rgba(255,255,255,0.05)" />
              <text x={padL - 8} y={y + 3.5} textAnchor="end" fontSize="10" fill="#64748b">
                {yLabel ? yLabel(v) : v.toFixed(0)}
              </text>
            </g>
          );
        })}
        {xLabels.map((l, i) => (
          <text
            key={i}
            x={padL + (cw / Math.max(xLabels.length - 1, 1)) * i}
            y={height - 6}
            textAnchor="middle"
            fontSize="10"
            fill="#64748b"
          >
            {l}
          </text>
        ))}
        {series.map((s, si) => {
          const pts: [number, number][] = s.data.map((v, i) => [
            padL + (i / Math.max(s.data.length - 1, 1)) * cw,
            8 + ch - (v / max) * ch,
          ]);
          const line = pathFrom(pts);
          const area = `${line} L${(padL + cw).toFixed(2)},${8 + ch} L${padL},${8 + ch} Z`;
          return (
            <g key={si}>
              <path d={area} fill={`url(#ag-${id}-${si})`} />
              <path d={line} fill="none" stroke={s.color} strokeWidth="2" strokeLinecap="round" />
            </g>
          );
        })}
      </svg>
    </div>
  );
}

export function Donut({
  segments,
  size = 132,
  thickness = 14,
  centerLabel,
  centerSub,
}: {
  segments: { value: number; color: string }[];
  size?: number;
  thickness?: number;
  centerLabel?: string;
  centerSub?: string;
}) {
  const total = segments.reduce((n, s) => n + s.value, 0) || 1;
  const r = (size - thickness) / 2;
  const c = 2 * Math.PI * r;
  let offset = 0;
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
      <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke="rgba(255,255,255,0.06)" strokeWidth={thickness} />
      {segments.map((s, i) => {
        const frac = s.value / total;
        const el = (
          <circle
            key={i}
            cx={size / 2}
            cy={size / 2}
            r={r}
            fill="none"
            stroke={s.color}
            strokeWidth={thickness}
            strokeLinecap="round"
            strokeDasharray={`${(frac * c).toFixed(2)} ${c.toFixed(2)}`}
            strokeDashoffset={(-offset * c).toFixed(2)}
            transform={`rotate(-90 ${size / 2} ${size / 2})`}
          />
        );
        offset += frac;
        return el;
      })}
      {centerLabel && (
        <text x="50%" y={centerSub ? "47%" : "52%"} textAnchor="middle" fontSize="20" fontWeight="700" fill="#f1f5f9">
          {centerLabel}
        </text>
      )}
      {centerSub && (
        <text x="50%" y="62%" textAnchor="middle" fontSize="10" fill="#64748b">
          {centerSub}
        </text>
      )}
    </svg>
  );
}

export function MeterBar({
  value,
  max,
  color = "#6f47f5",
  className = "",
}: {
  value: number;
  max: number;
  color?: string;
  className?: string;
}) {
  const pct = Math.min(100, (value / (max || 1)) * 100);
  return (
    <div className={`h-2 w-full rounded-full bg-white/[0.06] ${className}`}>
      <div
        className="h-2 rounded-full transition-all duration-500"
        style={{ width: `${pct}%`, background: `linear-gradient(90deg, #3b82f6, ${color})` }}
      />
    </div>
  );
}
--- AppLogo
/* eslint-disable @next/next/no-img-element */

/** Families that have a real brand SVG in /public/logos. */
const HAS_LOGO = new Set([
  "ubuntu", "debian", "almalinux", "rocky", "fedora", "centos", "arch", "alpine", "kali", "opensuse",
  "docker", "wordpress", "nextcloud", "nodejs", "caddy", "wireguard", "openvpn", "gitea", "jellyfin",
  "pihole", "uptimekuma", "vaultwarden", "cpanel", "plesk", "ghost", "grafana", "portainer", "minecraft",
]);

/** Emoji fallback for families with no brand SVG (mostly game servers / niche panels). */
const FALLBACK: Record<string, string> = {
  lamp: "💡", webmin: "🧰", cyberpanel: "🛡️", aapanel: "🅰️", hestiacp: "🌿", cloudpanel: "☁️",
  valheim: "🪓", rust: "🔩", palworld: "🐾", cs2: "🔫", terraria: "🌳", claude: "✦",
};

/**
 * Renders a product/OS/app/game logo. Real brand SVGs live in /public/logos; the
 * chip has a light background so both colored and dark logos stay visible on the
 * dark UI. Falls back to a tasteful emoji or the first letter.
 */
export function AppLogo({ family, name, size = 32 }: { family: string; name?: string; size?: number }) {
  const box = { width: size, height: size, minWidth: size };
  if (HAS_LOGO.has(family)) {
    return (
      <span
        className="flex items-center justify-center rounded-lg border border-white/10 bg-white/90 p-1.5"
        style={box}
      >
        <img src={`/logos/${family}.svg`} alt={name ?? family} className="h-full w-full object-contain" />
      </span>
    );
  }
  return (
    <span
      className="flex items-center justify-center rounded-lg border border-white/10 bg-white/[0.06] text-base"
      style={box}
    >
      {FALLBACK[family] ?? (name ?? family).charAt(0).toUpperCase()}
    </span>
  );
}

