== PortalHero.tsx:
import React from "react";

/**
 * PortalHero — the standard hero band at the top of every customer-portal page.
 * A drop-in upgrade of <PageHeader>: same `title` / `sub` / `children` (right-side
 * actions) API, plus a `variant` that selects a page-specific illustration and an
 * in-brand accent (violet · cyan · emerald · blue). It renders a compact glass
 * panel with a soft aura, a faint decorative grid, an accent orb, and a large
 * low-opacity glyph related to the page — consistent with the Deploy hub hero.
 *
 * Usage: replace `<PageHeader title=… sub=…>{actions}</PageHeader>` with
 *        `<PortalHero variant="servers" title=… sub=…>{actions}</PortalHero>`.
 */

type Accent = "violet" | "cyan" | "emerald" | "blue";

const ACCENT_HEX: Record<Accent, string> = {
  violet: "#6f47f5",
  cyan: "#22d3ee",
  emerald: "#10b981",
  blue: "#3b82f6",
};
const ACCENT_TEXT: Record<Accent, string> = {
  violet: "text-brand-300",
  cyan: "text-accent-cyan",
  emerald: "text-emerald-300",
  blue: "text-blue-300",
};

/** Stroke glyph per variant (24×24, currentColor). Kept inline so PortalHero has
 *  no external icon dependency and can never break a page with a missing import. */
const GLYPHS: Record<string, React.ReactNode> = {
  dashboard: <><rect x="3" y="3" width="8" height="8" rx="1.5" /><rect x="13" y="3" width="8" height="5" rx="1.5" /><rect x="13" y="10" width="8" height="11" rx="1.5" /><rect x="3" y="13" width="8" height="8" rx="1.5" /></>,
  deploy: <><path d="M12 2c3 2 4.5 5 4.5 8.5A4.5 4.5 0 0 1 12 15a4.5 4.5 0 0 1-4.5-4.5C7.5 7 9 4 12 2Z" /><path d="M8 15l-2 5 6-2 6 2-2-5" /><circle cx="12" cy="9" r="1.5" /></>,
  servers: <><rect x="3" y="4" width="18" height="7" rx="1.5" /><rect x="3" y="13" width="18" height="7" rx="1.5" /><path d="M7 7.5h.01M7 16.5h.01" /></>,
  hosting: <><circle cx="12" cy="12" r="9" /><path d="M3 12h18M12 3c2.5 2.4 3.8 5.6 3.8 9S14.5 18.6 12 21c-2.5-2.4-3.8-5.6-3.8-9S9.5 5.4 12 3Z" /></>,
  games: <><path d="M6 11h4M8 9v4M15.5 10.5h.01M18 12.5h.01" /><rect x="2.5" y="6.5" width="19" height="11" rx="5.5" /></>,
  nxcloud: <><path d="M7 18a4 4 0 0 1 0-8 5.5 5.5 0 0 1 10.7 1.5A3.5 3.5 0 0 1 17 18Z" /><path d="M12 12v5M9.5 14.5 12 12l2.5 2.5" /></>,
  volumes: <><ellipse cx="12" cy="6" rx="8" ry="3" /><path d="M4 6v6c0 1.7 3.6 3 8 3s8-1.3 8-3V6M4 12v6c0 1.7 3.6 3 8 3s8-1.3 8-3v-6" /></>,
  migrate: <><path d="M4 8h13M13 4l4 4-4 4M20 16H7M11 12l-4 4 4 4" /></>,
  domains: <><circle cx="12" cy="12" r="9" /><path d="M3 12h18M12 3c2.5 2.4 3.8 5.6 3.8 9S14.5 18.6 12 21" /><circle cx="17" cy="7" r="1.6" /></>,
