/** Which accent each variant carries. Defaults to violet. */
const VARIANT_ACCENT: Record<string, Accent> = {
  hosting: "cyan", migrate: "cyan", tools: "cyan",
  games: "emerald", ssl: "emerald",
  nxcloud: "blue", domains: "blue", mail: "blue", email: "blue", sites: "blue", calendar: "blue", support: "blue",
};

/** Short eyebrow label per variant. Falls back to none. */
const VARIANT_EYEBROW: Record<string, string> = {
  dashboard: "Overview", deploy: "Deploy", servers: "Compute", hosting: "Compute",
  games: "Compute", nxcloud: "Compute", volumes: "Storage", migrate: "Tools",
  domains: "Network", ssl: "Network", build: "Build", matrix: "Build",
  mail: "Mail", email: "Mail", tools: "Tools", billing: "Account", invoices: "Account",
  refer: "Account", team: "Account", support: "Account", activity: "Account",
  settings: "Account", projects: "Workspace", order: "Deploy", feedback: "Account",
  sites: "Network", calendar: "Network",
};

export function PortalHero({
  variant = "dashboard",
  title,
  sub,
  eyebrow,
  children,
}: {
  variant?: string;
  title: React.ReactNode;
  sub?: string;
  /** Override the default eyebrow label for this variant. */
  eyebrow?: string;
  /** Right-aligned actions, exactly like PageHeader. */
  children?: React.ReactNode;
}) {
  const accent: Accent = VARIANT_ACCENT[variant] ?? "violet";
  const hex = ACCENT_HEX[accent];
  const glyph = GLYPHS[variant] ?? GLYPHS.dashboard;
  const eb = eyebrow ?? VARIANT_EYEBROW[variant];

  return (
    <section className="relative mb-6 overflow-hidden rounded-3xl border border-white/[0.06] bg-navy-900/60 px-5 py-6 sm:px-7">
      {/* accent aura */}
      <div
        aria-hidden
        className="pointer-events-none absolute inset-0"
        style={{ background: `radial-gradient(90% 120% at 100% 0%, ${hex}22, transparent 60%)` }}
      />
      {/* faint grid + orb + big glyph on the right (hidden on small screens) */}
      <div aria-hidden className="pointer-events-none absolute inset-y-0 right-0 hidden w-1/2 sm:block">
        <svg viewBox="0 0 320 200" className="absolute right-0 top-1/2 h-[150%] w-auto -translate-y-1/2" fill="none" xmlns="http://www.w3.org/2000/svg">
          <defs>
            <radialGradient id={`ph-orb-${variant}`} cx="0.7" cy="0.4" r="0.6">
              <stop offset="0" stopColor={hex} stopOpacity="0.45" />
              <stop offset="1" stopColor={hex} stopOpacity="0" />
            </radialGradient>
            <pattern id={`ph-grid-${variant}`} width="26" height="26" patternUnits="userSpaceOnUse">
              <path d="M26 0H0V26" fill="none" stroke="#ffffff" strokeOpacity="0.04" strokeWidth="1" />
            </pattern>
          </defs>
          <rect x="0" y="0" width="320" height="200" fill={`url(#ph-grid-${variant})`} />
          <circle cx="230" cy="90" r="120" fill={`url(#ph-orb-${variant})`} />
          <g
            transform="translate(196 60) scale(3.4)"
            fill="none"
            stroke={hex}
            strokeOpacity="0.5"
            strokeWidth="1.4"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            {glyph}
          </g>
        </svg>
      </div>

      {/* Content sits in the LEFT column and the action buttons live UNDER the
          sub-text (not right-aligned), so a prominent CTA can never overlap the
          decorative illustration on the right. max-w keeps text off the artwork. */}
      <div className="relative max-w-[min(100%,42rem)]">
        {eb && (
          <span className={`section-label mb-2 flex items-center gap-2 ${ACCENT_TEXT[accent]}`}>
            <span className="h-1.5 w-1.5 rounded-full" style={{ background: hex }} />
            {eb}
          </span>
        )}
        <h1 className="page-title">{title}</h1>
        {sub && <p className="mt-1 text-sm text-slate-400">{sub}</p>}
        {children && <div className="mt-4 flex flex-wrap items-center gap-2">{children}</div>}
      </div>
    </section>
  );
}

